#!/usr/bin/env python3
"""Author and verify a separate genuine native Harkonnen tutorial save offline."""
from pathlib import Path
import argparse,hashlib,json,shutil,struct,subprocess,sys
ROOT=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 ap=argparse.ArgumentParser(description=__doc__);ap.add_argument('--fixture',type=Path,default=ROOT/'.local/campaign-fixtures/house0-mission09.cpu.bin');ap.add_argument('--evidence',type=Path,default=ROOT/'.local/training-fixture');ap.add_argument('--output',type=Path,default=ROOT/'data/training');ap.add_argument('--skip-compile',action='store_true');a=ap.parse_args()
 identity=json.loads((ROOT/'docs/source-identity.json').read_text());assert sha(ROOT/'.local/source/build/dune-base.c')==identity['generatedSourceSha256'];assert a.fixture.is_file()
 source=(ROOT/'.local/source/build/dune-web.c').read_text();start=source.index('#define DUNE_SAVESTATE_MAGIC ');end=source.index('EMSCRIPTEN_KEEPALIVE int dune_load_state_from_buffer',start);serializer=source[start:end];assert '#define DUNE_SAVESTATE_VERSION 2'in serializer;(ROOT/'.local/demo-save-serializer.inc').write_text(serializer)
 binary=ROOT/'.local/build-training-fixture';native=ROOT/'tools/build_training_fixture_native.c'
 if not a.skip_compile:subprocess.run(['clang','-std=c11','-O1',str(native),'-o',str(binary),'-lm'],cwd=ROOT,check=True)
 a.evidence.mkdir(parents=True,exist_ok=True);run=subprocess.run([str(binary),str(a.fixture),str(a.evidence)],cwd=ROOT,capture_output=True,text=True);(a.evidence/'build.log').write_text(run.stdout+run.stderr);print(run.stdout,end='')
 if run.returncode:print(run.stderr,file=sys.stderr,end='');run.check_returncode()
 setup=json.loads((a.evidence/'setup.json').read_text());model=json.loads((a.evidence/'training.json').read_text());state=a.evidence/'training.state.bin';payload=state.read_bytes()
 assert struct.unpack_from('<IIII',payload)==(0x56415344,2,0,len(payload));assert setup['disabledScheduledWaves']==11 and setup['disabledScriptedTeams']==6
 assert model['active']and model['house']==0 and model['mission']==9 and model['credits']==5000 and model['power']['production']>=model['power']['usage']and model['capacity']>=6000
 assert model['objects']['tank']['id']==43 and model['objects']['harvester']['id']==44 and model['objects']['enemy']['id']==45 and model['objects']['harvester']['cargo']==0
 assert 'PASS isolated original training fixture'in run.stdout
 a.output.mkdir(parents=True,exist_ok=True);shutil.copyfile(state,a.output/'training.state.bin');shutil.copyfile(state,ROOT/'web/training.state.bin')
 sys.path.insert(0,str(ROOT/'tools'));from extract_building_assets import png
 png(a.evidence/'training.png',320,224,(a.evidence/'training.rgb').read_bytes(),3)
 manifest={'version':1,'purpose':'Separate controlled original-program tutorial fixture; no earned campaign progress','house':0,'houseName':'Harkonnen','mission':9,'originalScenario':'SCENH009.INI','mapSeed':17,'source':identity,'payload':{'path':'training.state.bin','webPath':'training.state.bin','version':2,'bytes':len(payload),'sha256':sha(state)},'setup':setup,'initialNativeObserver':model,'observer':{'export':'dune_web_training_json','source':'tools/em_web_training.h','sha256':sha(ROOT/'tools/em_web_training.h'),'policy':'Whole-CPU-byte-identical read-only report. No runtime setter or gameplay patch.'},'provenance':{'sourceFixture':str(a.fixture.relative_to(ROOT)),'sourceFixtureSha256':sha(a.fixture),'nativeBuilder':'tools/build_training_fixture_native.c','nativeBuilderSha256':sha(native),'sharedOriginalHelperWrappers':'tools/build_demo_fixture_native.c','sharedHelperSha256':sha(ROOT/'tools/build_demo_fixture_native.c'),'driverSha256':sha(Path(__file__))},'nativeHelpers':{'buildingFree':'0x00BA56','unitRemove':'0x043504','emptyReinforcementSchedule':'Original161CE/161E8 sentinelFFFF atFFC0A2/stride10/count16','scriptedTeamReset':'0x02DE30(long0)','buildingCreate':'0x00E584','unitCreate':'0x0468BA','initialUnitGuardOrder':'0x0436A8','powerAndStorageRecount':'0x010490','initialFogUnveilCircle':'0x01A002','initialBankDisplayRefresh':'0x011F38'},'validation':{'readOnlyWholeCPU':True,'all4096TerrainValuesEqualOriginalClassifier':True,'nativeIdleFrames':108000,'tankRealMove':True,'originalBclear':True,'tankProjectileActualEnemyHP':True,'harvesterActualCargo':True,'nativeRefineryDeliveryCredits':True,'shopFirstTapPreviewSecondTapPaid':True,'nativeConcreteProductionAndPlacement':True,'continuousFullCargoSequenceWithoutRestore':True,'storedHarvesterRemainsAlive':True,'scheduledWavesRemovedOffline':True,'scriptedTeamsResetOffline':True},'rules':['Authored offline from original HarkonnenM9 terrain and native scenario flags.','Original helpers remove allocated roaming/off-map units and enemy production buildings; all16 reinforcement slots use the native empty FFFF sentinel and original Team_Reset removes scripted Teams. One remote original enemy Windtrap/storage remains to prevent an immediate victory.','Tank200HP, Harvester150HP and Soldier20HP retain original definitions, actions, projectiles and pathfinding. Initial Guard is a normal original scenario order.','Original concrete/building placement, native power/storage, and original fog-unveil circle prepare the training district.','5000 is the authored initial bank only. Harvesting and unloading must change actual cargo/credits through original execution.','No invulnerability, AI pause, timer acceleration, injected command success or runtime cheat API.','Host trainingMode must suppress all normal saves and campaign unlocks. Technical red demo remains a separate payload with all original enemies intact.'],'limitations':['Controlled authored tutorial, not an earned mission.','Normal units can be destroyed and original mission outcomes remain active.','Native/portable-save checks do not establish physical-phone playtesting.']}
 (a.output/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n');(ROOT/'web/training-manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'pass':True,'payload':'web/training.state.bin','sha256':sha(state),'initialCredits':5000,'objects':setup,'checks':manifest['validation']},ensure_ascii=False))
